<?php use Namira\{CallUI,CallEntries,Protocol};view('calls-assets'); ?>
<div class="heading"><h2>ارسال‌های من</h2><a class="primary" href="<?= e(url('calls')) ?>">مشاهده فراخوان‌ها</a></div>
<?php if($callNotifications): ?><details class="panel" open><summary>اعلان‌ها و پیام‌های دبیرخانه</summary><?php foreach($callNotifications as $n): ?><p <?= !$n['read_at']?'class="notice"':'' ?>><a href="<?= e(url('account',['section'=>'submissions','id'=>$n['submission_id']])) ?>"><?= e($n['message']) ?></a><small class="hint"> <?= fa($n['created_at']) ?></small></p><?php endforeach ?><form method="post"><?= CallUI::csrfForm('call2-notifications-read') ?><button class="outline">علامت‌گذاری اعلان‌ها به‌عنوان خوانده‌شده</button></form></details><?php endif ?>
<?php if($callEntry):$w=$callEntry;$b=$w['batch'];$call=Namira\CallCampaigns::get($db,(int)$w['call_id']); ?><article class="panel"><h3><?= e($w['title']) ?></h3><p>شهید: <?= e(Namira\CallMartyrFields::label($db,$b['data']['martyr'])) ?></p><p>بررسی: <?= e(CallEntries::statusLabel($w['review_state'])) ?> · انتشار: <?= e(CallUI::publicState($w['publication_state'])) ?></p><p>کد رهگیری: <b dir="ltr"><?= e($w['tracking']?:'هنوز ثبت نهایی نشده') ?></b></p><p>پیام دبیرخانه: <?= e($w['review_note']?:'پیامی ثبت نشده است.') ?></p><?php if($w['judgement_data']): ?><p>نتیجه داوری: <?= e(implode(' ـ ',array_filter($w['judgement_data']))) ?></p><?php endif ?>
<?php if($w['data']['text']): ?><details open><summary>متن اثر</summary><p class="prose"><?= e($w['data']['text']) ?></p></details><?php endif ?><div class="call-preview-grid"><?php foreach($w['files'] as $file): ?><a href="<?= e(url('call-file',['id'=>$file['asset_id']])) ?>"><?php if($file['preview_path']): ?><img src="<?= e(url('call-file',['id'=>$file['asset_id'],'size'=>'preview'])) ?>" alt="<?= e($file['filename']) ?>"><?php endif ?><span><?= e($file['filename']) ?></span></a><?php endforeach ?></div>
<?php if(CallEntries::canEdit($call,$w)): ?><a class="primary" href="<?= e(url('submit-art',['call_id'=>$w['call_id'],'batch'=>$w['batch_id'],'step'=>2,'work'=>$w['id']])) ?>">تکمیل یا اصلاح همین اثر</a><?php endif ?><?php if($w['publication_state']==='published'): ?><a class="outline" href="<?= e(url('profile',['id'=>$w['martyr_id']])) ?>">مشاهده نسخه منتشرشده در صفحه شهید</a><?php endif ?><details><summary>سابقه نسخه‌ها و بررسی</summary><?php foreach(Namira\Db::query($db,"SELECT to_status,note,created_at FROM submission_history WHERE entity_type='art_submission' AND entity_id=? ORDER BY id",[$w['id']])->fetchAll() as $h): ?><p><?= e(CallEntries::statusLabel($h['to_status'])) ?> · <?= fa($h['created_at']) ?></p><?php endforeach ?></details></article><?php endif ?>
<?php if($callsBatches): ?><details class="panel" <?= !$callEntry?'open':'' ?>><summary>پیش‌نویس‌ها و نوبت‌های ارسال</summary><?php foreach($callsBatches as $b):$proposal=Protocol::decode($b['payload'])['martyr']??[]; ?><article class="call-batch-row"><div><b><?= e($b['call_title']) ?></b><p><?= e(Namira\CallMartyrFields::label($db,$proposal)) ?> · <?= fa($b['work_count']) ?> اثر · <?= $b['state']==='draft'?'پیش‌نویس':'دارای ثبت نهایی' ?></p></div><a class="outline" href="<?= e(url('submit-art',['call_id'=>$b['call_id'],'batch'=>$b['id'],'step'=>1])) ?>">ادامه یا مشاهده</a></article><?php endforeach ?></details><?php endif ?>
<div class="call-account-works"><?php foreach($callsResult['items'] as $w):$proposal=Protocol::decode($w['batch_payload'])['martyr']??[]; ?><article class="panel"><h3><a href="<?= e(url('account',['section'=>'submissions','id'=>$w['id']])) ?>"><?= e($w['title']?:'اثر پیش‌نویس') ?></a></h3><p><?= e($w['call_title']) ?> · <?= e($w['section_title']) ?></p><p>شهید: <?= e(Namira\CallMartyrFields::label($db,$proposal)) ?></p><p>کد: <b dir="ltr"><?= e($w['tracking']?:'ثبت نهایی نشده') ?></b></p><p>بررسی: <?= e(CallEntries::statusLabel($w['review_state'])) ?> · انتشار: <?= e(CallUI::publicState($w['publication_state'])) ?></p><?php if($w['review_note']): ?><p class="notice"><?= e($w['review_note']) ?></p><?php endif ?><a class="outline" href="<?= e(url('account',['section'=>'submissions','id'=>$w['id']])) ?>">جزئیات و اقدام مجاز بعدی</a></article><?php endforeach ?></div>
<?php if(!$callsResult['items']&&!$callsBatches): ?><p class="empty">هنوز ارسال یا پیش‌نویسی ندارید.</p><?php endif ?><?php view('public-pagination',['count'=>$callsResult['count'],'per'=>$callsResult['per'],'page'=>$callsResult['page'],'route'=>'account','filters'=>['section'=>'submissions']]); ?>
<?php if($legacySubmissions): ?><details class="panel"><summary>ارسال‌های پیشین و مستقل از فراخوان جدید</summary><?php foreach($legacySubmissions as $s): ?><p><a href="<?= e(url('account',['section'=>'submissions','id'=>$s['id']])) ?>"><?= e($s['title']) ?></a></p><?php endforeach ?></details><?php endif ?>